// CreateTableWithDBType creates the Reservation_Entry table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *ReservationEntry) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, ReservationEntryTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetReservationEntryPostgresTableSchema()
	} else {
		schema = GetReservationEntryTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Reservation_Entry table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *ReservationEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, ReservationEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Reservation_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (reservation_status, item_no, variant_code, location_code, expected_receipt_date, for_type, for_subtype, for_id, for_batch_name, for_prod_order_line, for_ref_no, from_type, from_subtype, from_id, from_batch_name, from_prod_order_line, from_ref_no)`,
		fmt.Sprintf("%s$Reservation_Entry$status_item_for", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index status_item_for: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (reservation_status, item_no, variant_code, location_code, from_type, from_subtype, expected_receipt_date)`,
		fmt.Sprintf("%s$Reservation_Entry$status_item_from", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index status_item_from: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (reservation_status, for_type, for_subtype, for_id, for_batch_name, for_prod_order_line, for_ref_no, expected_receipt_date)`,
		fmt.Sprintf("%s$Reservation_Entry$status_for", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index status_for: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (reservation_status, from_type, from_subtype, from_id, from_batch_name, from_prod_order_line, from_ref_no, shipment_date)`,
		fmt.Sprintf("%s$Reservation_Entry$status_from", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index status_from: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (reservation_status, item_no, valid_to_date)`,
		fmt.Sprintf("%s$Reservation_Entry$status_item_valid_to", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index status_item_valid_to: %w", err)
	}
	var keys []sift.Key
	for _, spec := range reservationEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, ReservationEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, ReservationEntryTableName, keys)
}

// reservationEntrySIFTSpecs are the table's keys with sum_index_fields
func reservationEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *ReservationEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := tables.CompanyTable(t.company, ReservationEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range reservationEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, ReservationEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: ReservationEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, ReservationEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

